function(c){c._n=new PerlinNoise()},
function(c,w,h,t){c.fillStyle='rgba(0,0,0,.03)';c.fillRect(0,0,w,h);for(var i=0;i<4;i++){c.beginPath();for(var x=0;x<=w;x+=4){var y=c._n.noise2d(x*.003+i*.5+t*.0001,(i)*.3+t*.00008)*50+Math.sin(x*.005+t*.0015+i)*15+Math.sin((x+i)*.006+t*.0008)*10;c.lineTo(x,y+h*.5+i*20-40)}var hue=(i*60+t*.02)%360;c.strokeStyle='hsla('+hue+',80%,55%,.3)';c.lineWidth=2;c.stroke()}}
,'Multiple layered sine waves with varying amplitudes, colors, and phase offsets create the illusion of flowing northern lights.');})();

